param([Parameter(Mandatory=$true)][string]$RunName)
# Selector fixtures (selector_fixtures.py) are regenerated by every run and
# total about 4.9 GB per output directory (two 2 GB sparse card images).
# After a run, remove only those named fixture files, one path at a time;
# logs and metrics stay as evidence. Nothing outside the run directory.
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))
$dir=Join-Path $root "diagnostics/output/$RunName"
if(!(Test-Path $dir)){return}
$files=@(Get-ChildItem -LiteralPath $dir -File | Where-Object {$_.Name -match '^selector\d+(\.img|_bytes\.hex|_lba\.hex|_meta\.hex)$'})
foreach($file in $files){Remove-Item -LiteralPath $file.FullName}
Write-Output "removed $($files.Count) selector fixture files from $RunName"
